// src/router.rs
async fn get_config() -> Result<axum::Json<crate::config::Config>, Response> {
    match load_config("config.json") {
        Ok(config) => Ok(axum::Json(config)),
        Err(_) => Err(Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .body(axum::body::Body::empty())
            .unwrap()),
    }
}

// src/router.rs
pub fn router() -> Router {
    Router::new().route("/config", get(get_config))
}

